// ---------------------------------------------------------------------------
// ATS CV Renderer — rewritten for the standardized AI output schema.
// All legacy field-mapping / normalization logic has been removed.
//
// Expected schema:
// {
//   "name": "",
//   "title": "",
//   "contact": { "location": "", "phone": "", "email": "", "github": "", ... },
//   "professional_summary": "",
//   "skills": [ { "category": "", "keywords": [] } ],
//   "experience": [ { "title": "", "company": "", "location": "", "dates": "", "description": "" } ],
//   "projects": [ { "name": "", "tech_stack": [], "link": "", "description": "" } ],
//   "education": [ { "degree": "", "institution": "", "location": "", "dates": "" } ],
//   "certifications": [ { "name": "", "issuer": "", "date": "" } ],
//   "languages": []
// }
// ---------------------------------------------------------------------------

const rawInput = $json || {};
const data = Array.isArray(rawInput) ? (rawInput[0] || {}) : rawInput;

// This is about *where the schema object sits in the incoming payload*
// (workflow wiring), not about legacy field mapping inside the schema
// itself — kept minimal on purpose. Adjust if your upstream node changes.
const cv = data.optimized_cv || data.cv || data;

// ---------------------------------------------------------------------------
// Small helpers
// ---------------------------------------------------------------------------

function esc(value) {
  return String(value ?? "")
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;")
    .replace(/'/g, "&#039;");
}

function arr(value) {
  return Array.isArray(value) ? value.filter(Boolean) : [];
}

function normalizeFileName(name) {
  return String(name || "ATS_Optimized_CV")
    .trim()
    .replace(/[^\p{L}\p{N}]+/gu, "_")
    .replace(/^_+|_+$/g, "") || "ATS_Optimized_CV";
}

function renderSection(title, body) {
  if (!body || !String(body).trim()) return "";
  return `
    <section>
      <h2>${esc(title)}</h2>
      ${body}
    </section>
  `;
}

function linkText(value) {
  return String(value || "")
    .replace(/^https?:\/\//i, "")
    .replace(/\/$/g, "");
}

function isRealLink(value) {
  const link = String(value || "").trim();
  if (!link) return false;
  return (
    /^https?:\/\//i.test(link) ||
    /^[a-z0-9-]+(\.[a-z0-9-]+)+(\/[^\s]*)?$/i.test(link)
  );
}

function makeUrl(url) {
  if (!url) return "";
  const clean = String(url).trim();
  return clean.startsWith("http") ? clean : `https://${clean}`;
}

function titleCaseLabel(key) {
  return String(key || "")
    .replace(/[_-]+/g, " ")
    .trim()
    .replace(/\b\w/g, c => c.toUpperCase());
}

// ---------------------------------------------------------------------------
// Basic fields
// ---------------------------------------------------------------------------

const candidateName = cv.name || "Candidate";
const title = cv.title || "";
const summary = cv.professional_summary || "";

// FIX #5: contact parsing now uses `cv.contact` only.
const contact = cv.contact || {};
const location = contact.location || "";
const phone = contact.phone || "";
const email = contact.email || "";

// Any other string field on `contact` that looks like a URL is treated as a
// link (github, linkedin, portfolio, projects_doc, etc.) and rendered with a
// friendly label — no separate normalization pass needed.
const KNOWN_LINK_LABELS = {
  github: "GitHub",
  linkedin: "LinkedIn",
  portfolio: "Portfolio",
  projects_doc: "Project Docs",
  behance: "Behance",
  twitter: "Twitter",
  medium: "Medium",
  website: "Website",
  blog: "Blog"
};

const contactLinks = {};
for (const [key, value] of Object.entries(contact)) {
  if (key === "location" || key === "phone" || key === "email") continue;
  if (typeof value !== "string" || !isRealLink(value)) continue;
  contactLinks[KNOWN_LINK_LABELS[key] || titleCaseLabel(key)] = value;
}

const contactInfoHtml = [location, phone, email]
  .filter(Boolean)
  .map(v => `<span>${esc(v)}</span>`)
  .join("");

const contactLinksHtml = Object.entries(contactLinks)
  .map(([label, url]) =>
    `<span>${esc(label)}: <a href="${makeUrl(url)}" class="link" target="_blank">${esc(linkText(url))}</a></span>`
  )
  .join("");

// ---------------------------------------------------------------------------
// FIX #4: Skills — render only skill.category / skill.keywords.
// ---------------------------------------------------------------------------

const skillsHtml = arr(cv.skills).map(group => {
  const keywords = arr(group.keywords);
  if (!keywords.length) return "";
  return `
    <div class="skill-group">
      <div class="skill-label">${esc(group.category || "")}</div>
      <div class="skill-values">${keywords.map(esc).join(", ")}</div>
    </div>
  `;
}).join("");

const skillsBlock = skillsHtml ? `<div class="skills-grid">${skillsHtml}</div>` : "";

// ---------------------------------------------------------------------------
// FIX #1: Experience — read exp.description directly, no bullet merging.
// ---------------------------------------------------------------------------

const experienceHtml = arr(cv.experience).map(exp => {
  const paragraph = exp.description || "";

  return `
    <div class="item">
      <div class="item-header">
        <div class="item-title">
          <strong>${esc(exp.title || "")}</strong>${exp.company ? ` | ${esc(exp.company)}` : ""}${exp.location ? ` | ${esc(exp.location)}` : ""}
        </div>
        <div class="item-date">${esc(exp.dates || "")}</div>
      </div>
      ${paragraph ? `<div class="desc">${esc(paragraph)}</div>` : ""}
    </div>
  `;
}).join("");

// ---------------------------------------------------------------------------
// FIX #2 + #3: Projects — read project.description and project.tech_stack
// directly, no bullet/highlight merging.
// ---------------------------------------------------------------------------

const projectsHtml = arr(cv.projects).map(project => {
  const technologies = arr(project.tech_stack);
  const link = isRealLink(project.link) ? project.link : "";
  const paragraph = project.description || "";

  return `
    <div class="item project-item">
      <div class="item-header">
        <div class="item-title">
          <strong>${esc(project.name || "")}</strong>${technologies.length ? `<span class="tech-list"> | ${esc(technologies.join(", "))}</span>` : ""}
        </div>

        ${link ? `
          <div class="item-date">
            <a href="${makeUrl(link)}" class="link" target="_blank">${esc(linkText(link))}</a>
          </div>
        ` : ""}
      </div>

      ${paragraph ? `<div class="desc">${esc(paragraph)}</div>` : ""}
    </div>
  `;
}).join("");

// ---------------------------------------------------------------------------
// FIX #6: Education — read degree / institution / location / dates directly.
// ---------------------------------------------------------------------------

const educationHtml = arr(cv.education).map(edu => {
  return `
    <div class="item">
      <div class="item-header">
        <div class="item-title">
          <strong>${esc(edu.degree || "")}</strong>
          ${edu.institution ? ` | ${esc(edu.institution)}` : ""}
          ${edu.location ? ` | ${esc(edu.location)}` : ""}
        </div>
        <div class="item-date">${esc(edu.dates || "")}</div>
      </div>
    </div>
  `;
}).join("");

// ---------------------------------------------------------------------------
// FIX #7: Certifications — read name / issuer / date directly.
// ---------------------------------------------------------------------------

const certifications = arr(cv.certifications);
const certificationsHtml = certifications.length
  ? `<ul class="cert-list">${certifications.map(cert => {
      const meta = [cert.issuer, cert.date].filter(Boolean).join(" | ");
      return `<li><strong>${esc(cert.name || "")}</strong>${meta ? ` — ${esc(meta)}` : ""}</li>`;
    }).join("")}</ul>`
  : "";

// ---------------------------------------------------------------------------
// Languages
// ---------------------------------------------------------------------------

const languages = arr(cv.languages);
const languagesHtml = languages.length
  ? `<p>${languages.map(lang =>
      typeof lang === "object"
        ? `${esc(lang.language || "")}${lang.level ? ` (${esc(lang.level)})` : ""}`
        : esc(lang)
    ).join(" | ")}</p>`
  : "";

// ---------------------------------------------------------------------------
// FIX #8: Density — based on item counts + description length, not bullets.
// ---------------------------------------------------------------------------

const experienceList = arr(cv.experience);
const projectsList = arr(cv.projects);
const educationList = arr(cv.education);

const descriptionWeight = [...experienceList, ...projectsList].reduce(
  (sum, item) => sum + Math.round(String(item.description || "").length / 150),
  0
);

const density =
  experienceList.length +
  projectsList.length +
  educationList.length +
  certifications.length +
  descriptionWeight;

let densityTier = "normal";
if (density > 16) densityTier = "very-dense";
else if (density > 10) densityTier = "dense";

const DENSITY_CSS = {
  normal: { base: "11.3px", line: "1.5", sectionGap: "13px", itemGap: "7px" },
  dense: { base: "10.6px", line: "1.42", sectionGap: "10px", itemGap: "5px" },
  "very-dense": { base: "10px", line: "1.35", sectionGap: "8px", itemGap: "4px" }
}[densityTier];

// ---------------------------------------------------------------------------
// HTML assembly
// ---------------------------------------------------------------------------

const html = `<!doctype html>
<html lang="en">
<head>
<meta charset="UTF-8" />
<title>${esc(candidateName)} - ATS Optimized CV</title>

<style>
  @page {
    size: A4;
    margin: 0;
  }

  :root {
    --base-font: ${DENSITY_CSS.base};
    --line-height: ${DENSITY_CSS.line};
    --section-gap: ${DENSITY_CSS.sectionGap};
    --item-gap: ${DENSITY_CSS.itemGap};
  }

  * { box-sizing: border-box; }

  body {
    margin: 0;
    padding: 0;
    background: #ffffff;
    color: #111111;
    font-family: Arial, Helvetica, sans-serif;
    font-size: var(--base-font);
    line-height: var(--line-height);
  }

  .page {
    width: 210mm;
    min-height: 297mm;
    padding: 10mm 16mm;
    margin: 0 auto;
    background: #ffffff;
  }

  header {
    text-align: center;
    padding-bottom: 8px;
    margin-bottom: var(--section-gap);
  }

  h1 {
    margin: 0;
    font-size: 26px;
    line-height: 1.1;
    font-weight: 600;
    text-transform: uppercase;
    letter-spacing: 0.3px;
  }

  .title {
    margin-top: 6px;
    font-size: 12px;
    font-weight: 400;
  }

  .contact {
    margin-top: 6px;
    font-size: 10px;
    color: #111111;
    word-break: break-word;
    line-height: 1.6;
  }

  .contact-row {
    display: flex;
    flex-wrap: wrap;
    justify-content: center;
    gap: 0;
  }

  .contact-cluster span:not(:last-child)::after {
    content: " | ";
    color: #111111;
  }

  .links-cluster {
    margin-left: 16px;
  }

  .link { color: #0066cc; text-decoration: none; }
  .link:hover { text-decoration: underline; }

  section { margin-top: var(--section-gap); }

  h2 {
    margin: 0 0 6px 0;
    padding-bottom: 3px;
    border-bottom: 1px solid #d0d0d0;
    font-size: 13.5px;
    line-height: 1.2;
    font-weight: 700;
    text-transform: uppercase;
    letter-spacing: 0.2px;
  }

  p { margin: 0 0 5px 0; }

  .skills-grid {
    display: grid;
    grid-template-columns: repeat(2, 1fr);
    column-gap: 16px;
    row-gap: 3px;
  }

  .skill-group { break-inside: avoid; }

  .skill-label { font-weight: 700; display: inline; }
  .skill-values { display: inline; }

  .item {
    margin-bottom: var(--item-gap);
    break-inside: avoid;
  }

  .project-item { margin-bottom: var(--item-gap); }

  .item-header {
    display: flex;
    justify-content: space-between;
    align-items: baseline;
    gap: 12px;
  }

  .item-title { flex: 1; font-weight: 700; }

  .tech-list {
    font-weight: 400;
    font-size: 10px;
    color: #555555;
  }

  .item-date {
    white-space: nowrap;
    text-align: right;
    color: #111111;
    font-size: 9.6px;
    font-weight: 700;
  }

  .sub { margin-top: 2px; color: #333333; font-size: 10px; }

  ul { margin: 3px 0 0 15px; padding: 0; }
  li { margin: 0 0 2px 0; padding: 0; }

  .cert-list { margin: 0 0 0 15px; }

  .desc { margin-top: 2px; }

  .footer-grid {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 18px;
  }
</style>
</head>

<body>
  <main class="page">

    <header>
      <h1>${esc(candidateName)}</h1>
      ${title ? `<div class="title">${esc(title)}</div>` : ""}

      <div class="contact">
        <div class="contact-row">
          ${contactInfoHtml ? `<span class="contact-cluster">${contactInfoHtml}</span>` : ""}
          ${contactLinksHtml ? `<span class="contact-cluster links-cluster">${contactLinksHtml}</span>` : ""}
        </div>
      </div>
    </header>

    ${summary ? `<section><h2>Professional Summary</h2><p>${esc(summary)}</p></section>` : ""}

    ${renderSection("Skills", skillsBlock)}
    ${renderSection("Experience", experienceHtml)}
    ${renderSection("Projects", projectsHtml)}
    ${renderSection("Education", educationHtml)}

    ${
      certificationsHtml || languagesHtml
        ? `<div class="footer-grid">
            ${renderSection("Certifications", certificationsHtml)}
            ${renderSection("Languages", languagesHtml)}
          </div>`
        : ""
    }

  </main>
</body>
</html>`;

const safeName = normalizeFileName(candidateName);
const pdfFileName = `${safeName}_ATS_Optimized_CV.pdf`;

const htmlBuffer = Buffer.from(html, "utf8");

const binaryData = await this.helpers.prepareBinaryData(
  htmlBuffer,
  "index.html",
  "text/html"
);

return {
  json: {
    ...data,
    ok: true,
    success: true,
    status: "ats_cv_html_built",
    chat_id: String(data.chat_id || data.chatId || ""),
    chatId: String(data.chatId || data.chat_id || ""),
    user_id: data.user_id,
    session_id: data.session_id,
    user_file_id: data.user_file_id,
    fileName: pdfFileName,
    file_name: pdfFileName,
    pdf_file_name: pdfFileName,
    density,
    density_tier: densityTier,
    html,
    html_length: html.length,
    html_ready: true
  },
  binary: {
    data: binaryData
  }
};

const pdfItem = $input.first();

let htmlNodeData = {};
let requestData = {};

try {
  htmlNodeData = $("Build One-Page CV HTML Binary").first().json || {};
} catch (error) {
  htmlNodeData = {};
}

try {
  requestData = $("Normalize Optimized CV Request").first().json || {};
} catch (error) {
  requestData = {};
}

const chatId = String(
  requestData.chat_id ||
  requestData.chatId ||
  htmlNodeData.chat_id ||
  htmlNodeData.chatId ||
  pdfItem.json?.chat_id ||
  pdfItem.json?.chatId ||
  ""
);

const userId = String(
  requestData.user_id ||
  htmlNodeData.user_id ||
  pdfItem.json?.user_id ||
  ""
);

const sessionId = String(
  requestData.session_id ||
  htmlNodeData.session_id ||
  pdfItem.json?.session_id ||
  ""
);

const fileName =
  htmlNodeData.pdf_file_name ||
  htmlNodeData.fileName ||
  htmlNodeData.file_name ||
  pdfItem.json?.pdf_file_name ||
  pdfItem.json?.fileName ||
  pdfItem.json?.file_name ||
  "optimized_cv.pdf";

// Detect binary property from Generate PDF
const binaryKeys = Object.keys(pdfItem.binary || {});

const detectedBinaryProperty =
  pdfItem.binary?.pdf
    ? "pdf"
    : pdfItem.binary?.data
      ? "data"
      : binaryKeys[0] || "";

const pdfBinary = detectedBinaryProperty
  ? pdfItem.binary[detectedBinaryProperty]
  : null;

if (!pdfBinary) {
  return [
    {
      json: {
        ok: false,
        success: false,
        status: "pdf_generation_failed",

        chat_id: chatId,
        user_id: userId,
        session_id: sessionId,

        error: {
          code: "PDF_BINARY_NOT_FOUND",
          message: "PDF binary output was not found after Generate PDF node."
        },

        reply: {
          type: "text",
          text: "⚠️ حدث خطأ أثناء إنشاء ملف PDF. رجاءً حاول مرة أخرى.",
          buttons: [
            {
              label: "🔁 Try Again",
              action: "GENERATE_OPTIMIZED_CV_PDF"
            },
            {
              label: "🏠 Main Menu",
              action: "MAIN_MENU"
            }
          ],
          file: null
        },

        meta: {
          source_workflow: "WF_12_Generate_Optimized_CV_PDF",
          source_node: "Build Telegram PDF Response"
        }
      }
    }
  ];
}

// Normalize binary metadata
pdfBinary.fileName = fileName;
pdfBinary.mimeType = "application/pdf";
pdfBinary.fileExtension = "pdf";

const outputBinaryProperty = "pdf";

return [
  {
    json: {
      ok: true,
      success: true,
      status: "optimized_cv_pdf_generated",

      chat_id: chatId,
      chatId: chatId,

      user_id: userId,
      session_id: sessionId,

      reply: {
        type: "document",
        text: "✅ تم إنشاء نسخة CV محسّنة بصيغة PDF.",
        caption: "✅ تم إنشاء نسخة CV محسّنة بصيغة PDF.",
        filename: fileName,

        binary_property: outputBinaryProperty,

        file: {
          binaryProperty: outputBinaryProperty,
          fileName: fileName,
          mimeType: "application/pdf"
        },

        buttons: [
          {
            label: "✉️ Generate Cover Letter PDF",
            action: "GENERATE_COVER_LETTER_PDF"
          },
          {
            label: "🏠 Main Menu",
            action: "MAIN_MENU"
          }
        ]
      },

      meta: {
        source_workflow: "WF_12_Generate_Optimized_CV_PDF",
        source_node: "Build Telegram PDF Response",

        user_id: userId,
        session_id: sessionId,
        chat_id: chatId,

        file_name: fileName,
        original_binary_property: detectedBinaryProperty
      }
    },

    binary: {
      pdf: pdfBinary
    }
  }
];

const input = $input.first().json;

return [
{
  json: {
    user_id: input.user?.id,
    chat_id: input.user?.channel_user_id,
    channel: input.user?.channel,
    session_id: input.active_session?.id,
    file_name: input.file?.file_name,
    file_type: input.file_type,

    cv_text:
      input?.file_context?.extracted_text?.clean_text ||
      input?.data?.clean_text ||
      input?.data?.structured_text ||
      ""
  }
}
];

const data = $json || {};

const cv =
  data.original_cv ||
  data.cv_json ||
  data.optimized_cv ||
  data.cv ||
  data.optimizedCV ||
  data.analysis?.optimizedOnePageCV ||
  data;

function esc(value) {
  return String(value ?? "")
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;")
    .replace(/'/g, "&#039;");
}

function arr(value) {
  if (!value) return [];

  if (Array.isArray(value)) {
    return value.filter(item => {
      if (!item) return false;

      if (typeof item === "object") {
        return Object.values(item).some(v => {
          if (Array.isArray(v)) return v.length > 0;
          return v !== null && v !== undefined && String(v).trim() !== "";
        });
      }

      return String(item).trim() !== "";
    });
  }

  if (typeof value === "string") {
    return value
      .split(/\n|•|,/)
      .map(x => x.trim())
      .filter(Boolean);
  }

  return [];
}

function firstNonEmpty(...values) {
  for (const value of values) {
    if (value === null || value === undefined) continue;

    if (Array.isArray(value) && value.length) return value;

    if (
      typeof value === "object" &&
      !Array.isArray(value) &&
      Object.keys(value).length
    ) {
      return value;
    }

    if (typeof value !== "object" && String(value).trim() !== "") {
      return value;
    }
  }

  return "";
}

function normalizeFileName(name) {
  return String(name || "ATS_Optimized_CV")
    .trim()
    .replace(/[^\p{L}\p{N}]+/gu, "_")
    .replace(/^_+|_+$/g, "") || "ATS_Optimized_CV";
}

// ---------- Space-optimization helpers ----------

// Caps a description to a max word count, keeping it dense and ATS-friendly.
function truncateWords(text, maxWords = 25) {
  const words = String(text || "").trim().split(/\s+/).filter(Boolean);
  if (!words.length) return "";
  if (words.length <= maxWords) return words.join(" ");
  return words.slice(0, maxWords).join(" ").replace(/[.,;:]+$/, "") + "...";
}

// Case-insensitive de-duplication that preserves original casing of first occurrence.
function dedupeCaseInsensitive(list) {
  const seen = new Set();
  const out = [];
  for (const item of list) {
    const key = String(item).trim().toLowerCase();
    if (!key || seen.has(key)) continue;
    seen.add(key);
    out.push(item);
  }
  return out;
}

// Removes items from `list` whose lowercase form is already present in `seenSet`,
// and adds newly-kept items to `seenSet` (used to cross-dedupe skill groups).
function dedupeAgainst(list, seenSet) {
  const out = [];
  for (const item of list) {
    const key = String(item).trim().toLowerCase();
    if (!key || seenSet.has(key)) continue;
    seenSet.add(key);
    out.push(item);
  }
  return out;
}

// Flags a bullet that is essentially just a restatement of skills already listed
// in the Skills section, so Experience doesn't repeat technologies verbatim.
function isSkillRestatement(bulletText, skillSet) {
  if (!skillSet.size) return false;
  const words = String(bulletText)
    .toLowerCase()
    .split(/[^a-z0-9+.#]+/)
    .filter(Boolean);
  if (!words.length || words.length > 10) return false;
  const matches = words.filter(w => skillSet.has(w));
  return matches.length / words.length >= 0.5;
}

// Builds a compact, paragraph-style experience blurb (max N sentences)
// instead of a bullet list, per resume formatting requirements.
function buildExperienceParagraph(items, maxSentences = 2) {
  const cleaned = items
    .map(b => String(b).trim().replace(/[.\s]+$/, ""))
    .filter(Boolean);

  const capped = cleaned.slice(0, maxSentences);
  if (!capped.length) return "";

  return capped.map(s => `${s}.`).join(" ");
}

function renderSkillGroup(label, items) {
  const values = arr(items);
  if (!values.length) return "";

  return `
    <p class="skill-line">
      <strong>${esc(label)}:</strong> ${values.map(esc).join(", ")}.
    </p>
  `;
}

function renderBullets(items, max = 3) {
  const values = arr(items).slice(0, max);
  if (!values.length) return "";

  return `
    <ul>
      ${values.map(item => `<li>${esc(item)}</li>`).join("")}
    </ul>
  `;
}

function renderSection(title, body) {
  if (!body || !String(body).trim()) return "";

  return `
    <section>
      <h2>${esc(title)}</h2>
      ${body}
    </section>
  `;
}

function linkText(value) {
  return String(value || "")
    .replace(/^https?:\/\//i, "")
    .replace(/\/$/g, "");
}

function isRealLink(value) {
  const link = String(value || "").trim();

  return (
    /^https?:\/\//i.test(link) ||
    /github\.com|linkedin\.com|web\.app|netlify\.app|vercel\.app/i.test(link)
  );
}

function makeUrl(url) {
  if (!url) return "";

  const clean = String(url).trim();

  return clean.startsWith("http")
    ? clean
    : `https://${clean}`;
}

const personal =
  cv.personal ||
  cv.personal_info ||
  cv.personalInfo ||
  cv.contact ||
  {};

const candidateName = firstNonEmpty(
  personal.full_name,
