// Flat lowercase skill set, used to keep Experience paragraphs from repeating
// technologies already shown in the Skills section. Walks every possible
// skills field (dynamic categories, legacy categorized, legacy flat, and any
// unanticipated keys) so it stays in sync with whatever skillsHtml renders.
const flatSkillSet = new Set(
  (() => {
    const all = [];

    if (Array.isArray(skills?.categories)) {
      for (const group of skills.categories) {
        all.push(...arr(group?.items));
      }
    }

    const knownKeys = [
      "frontend", "backend", "database", "db",
      "ai_automation", "aiAutomation", "tools_ai", "ai",
      "technical", "tools", "other", "soft", "soft_skills"
    ];

    for (const key of knownKeys) {
      all.push(...arr(skills?.[key]));
    }

    if (skills && typeof skills === "object" && !Array.isArray(skills)) {
      for (const key of Object.keys(skills)) {
        if (key === "categories" || knownKeys.includes(key)) continue;
        const value = skills[key];
        if (Array.isArray(value) || typeof value === "string") {
          all.push(...arr(value));
        }
      }
    }

    if (Array.isArray(skills)) all.push(...arr(skills));

    return all.map(skill => String(skill).toLowerCase());
  })()
);

// ---------- Skills rendering: fully schema-agnostic, dynamic, and profession-independent ----------
// Every possible category (new dynamic schema, legacy categorized schema,
// legacy flat schema, or any unanticipated key the AI invents) is collected
// into one ordered list of {label, items} groups, deduped by label, and ALL
// non-empty groups are rendered together. No branch short-circuits or hides
// another — a skill present anywhere in the input is never dropped, and no
// category name (Frontend/Backend/Database/etc.) is assumed to be required
// or exhaustive; they're just recognized aliases for nicer labels when present.
function titleCaseLabel(key) {
  return String(key || "")
    .replace(/[_-]+/g, " ")
    .replace(/\s+/g, " ")
    .trim()
    .replace(/\b\w/g, c => c.toUpperCase());
}

const skillsHtml = (() => {
  const groups = []; // ordered list of { label, items }
  const seenLabels = new Set(); // lowercase label already added

  function addGroup(label, items) {
    const values = dedupeCaseInsensitive(arr(items));
    if (!values.length) return;

    const key = String(label).trim().toLowerCase();
    if (seenLabels.has(key)) return; // don't render the same category twice
    seenLabels.add(key);

    groups.push({ label, items: values });
  }

  // 1) Dynamic categories schema: { categories: [{ name, items }] }
  if (Array.isArray(skills?.categories)) {
    for (const group of skills.categories) {
      if (!group) continue;
      addGroup(group.name || "Skills", group.items);
    }
  }

  // 2) Legacy categorized + legacy flat schema keys — all recognized keys are
  //    rendered under a human-readable label. Presence of one key (e.g. "tools")
  //    never suppresses another (e.g. "technical"); every non-empty key renders.
  const legacyKnown = [
    ["Frontend", skills?.frontend],
    ["Backend", skills?.backend],
    ["Database", skills?.database || skills?.db],
    ["AI & Automation", skills?.ai_automation || skills?.aiAutomation || skills?.tools_ai || skills?.ai],
    ["Technical", skills?.technical],
    ["Tools", skills?.tools],
    ["Soft Skills", skills?.soft || skills?.soft_skills],
    ["Other", skills?.other]
  ];

  for (const [label, items] of legacyKnown) {
    addGroup(label, items);
  }

  // 3) Any other, unanticipated keys on the skills object — profession-agnostic
  //    catch-all so a category like "Lab Techniques", "Clinical Skills",
  //    "Accounting Software", or any future AI-invented category still renders.
  const reservedKeys = new Set([
    "categories", "frontend", "backend", "database", "db",
    "ai_automation", "aiAutomation", "tools_ai", "ai",
    "technical", "tools", "soft", "soft_skills", "other"
  ]);

  if (skills && typeof skills === "object" && !Array.isArray(skills)) {
    for (const key of Object.keys(skills)) {
      if (reservedKeys.has(key)) continue;
      const value = skills[key];
      if (Array.isArray(value) || typeof value === "string") {
        addGroup(titleCaseLabel(key), value);
      }
    }
  }

  // 4) Ultimate fallback: skills itself is just a flat array with no categorization
  if (!groups.length && Array.isArray(skills)) {
    addGroup("Skills", skills);
  }

  return groups.map(g => renderSkillGroup(g.label, g.items)).join("");
})();

