// Flat lowercase skill set, used to keep Experience bullets from repeating
// technologies already shown in the Skills section.
const flatSkillSet = new Set(
  [
    ...arr(skills.frontend),
    ...arr(skills.integration),
    ...arr(skills.tools_ai),
    ...arr(skills.technical),
    ...arr(skills.tools),
    ...arr(skills.backend),
    ...arr(skills.other),
    ...arr(skills.soft),
    ...arr(skills.soft_skills)
  ].map(s => String(s).toLowerCase())
);

const skillsHtml = (() => {
  const frontend = dedupeCaseInsensitive(arr(skills.frontend));
  const integration = dedupeCaseInsensitive(arr(skills.integration));
  const toolsAi = dedupeCaseInsensitive(arr(skills.tools_ai));
  const softGrouped = dedupeCaseInsensitive(arr(skills.soft || skills.soft_skills));

  const hasGroupedSkills = frontend.length || integration.length || toolsAi.length;

  if (hasGroupedSkills) {
    const totalGrouped = frontend.length + integration.length + toolsAi.length + softGrouped.length;

    // Reduce unnecessary categorization when information is limited.
    if (totalGrouped <= 5) {
      const merged = dedupeCaseInsensitive([...frontend, ...integration, ...toolsAi, ...softGrouped]);
      return renderSkillGroup("Skills", merged);
    }

    // Cross-dedupe: a skill already shown in an earlier group won't repeat in a later one.
    const seen = new Set(frontend.map(s => s.toLowerCase()));
    const integrationUnique = dedupeAgainst(integration, seen);
    const toolsAiUnique = dedupeAgainst(toolsAi, seen);
    const softUnique = dedupeAgainst(softGrouped, seen);

    return [
      renderSkillGroup("Frontend", frontend),
      renderSkillGroup("Integration", integrationUnique),
      renderSkillGroup("Tools & AI", toolsAiUnique),
      renderSkillGroup("Soft Skills", softUnique)
    ].join("");
  }

  const technical = dedupeCaseInsensitive(arr(
    skills.technical?.length
      ? skills.technical
      : [
          ...arr(skills.frontend),
          ...arr(skills.backend),
          ...arr(skills.integration),
          ...arr(skills.other)
        ]
  ));

  const seenFlat = new Set(technical.map(s => s.toLowerCase()));

  const tools = dedupeAgainst(
    dedupeCaseInsensitive(arr(skills.tools?.length ? skills.tools : skills.tools_ai)),
    seenFlat
  );

  const soft = dedupeAgainst(
    dedupeCaseInsensitive(arr(skills.soft || skills.soft_skills)),
    seenFlat
  );

  const totalFlat = technical.length + tools.length + soft.length;

  // Reduce unnecessary categorization when information is limited.
  if (totalFlat > 0 && totalFlat <= 5) {
    return renderSkillGroup("Skills", [...technical, ...tools, ...soft]);
  }

  return [
    renderSkillGroup("Technical", technical),
    renderSkillGroup("Tools", tools),
    renderSkillGroup("Soft Skills", soft)
  ].join("");
})();

