const safeName = normalizeFileName(candidateName);
const pdfFileName = `${safeName}_ATS_Optimized_CV.pdf`;

const htmlBuffer = Buffer.from(html, "utf8");

const binaryData = await this.helpers.prepareBinaryData(
  htmlBuffer,
