// ============================================================================
// ATS CV RENDERER — visually enhanced, content-preserving, production-ready (v9)
// ============================================================================
// التصحيح: التأكد من أن الحقول النصية (link, title, subtitle, date, location) 
//          هي سلاسل نصية وليست مصفوفات أو كائنات.
// ============================================================================

const data = $json || {};
const input = data.optimized_cv || data.cv || data.optimizedCV ||
             data.analysis?.optimizedOnePageCV || {};

// ----------------------------------------------------------------------------
// 1. HELPERS – with improved URL detection
// ----------------------------------------------------------------------------

function decodeEntities(str) {
  return String(str ?? "")
    .replace(/&amp;/g, "&")
    .replace(/&lt;/g, "<")
    .replace(/&gt;/g, ">")
    .replace(/&quot;/g, '"')
    .replace(/&#0?39;/g, "'");
}

function esc(value) {
  return decodeEntities(value)
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;")
    .replace(/'/g, "&#039;");
}

function toArray(value) {
  if (value == null) return [];
  if (Array.isArray(value)) {
    return value.filter(item => {
      if (item == null) return false;
      if (typeof item === "object") {
        return Object.values(item).some(v => {
          if (Array.isArray(v)) return v.length > 0;
          return v != null && String(v).trim() !== "";
        });
      }
      return String(item).trim() !== "";
    });
  }
  if (typeof value === "object") {
    const hasContent = Object.values(value).some(v => {
      if (Array.isArray(v)) return v.length > 0;
      return v != null && String(v).trim() !== "";
    });
    return hasContent ? [value] : [];
  }
  if (typeof value === "string") {
    return value.trim() ? [value] : [];
  }
  return [];
}

function firstNonEmpty(...values) {
  for (const v of values) {
    if (v == null) continue;
    if (Array.isArray(v) && v.length) return v;
    if (typeof v === "object" && !Array.isArray(v) && Object.keys(v).length) return v;
    if (typeof v !== "object" && String(v).trim() !== "") return v;
  }
  return "";
}

function isPlaceholder(value) {
  if (value == null) return true;
  const str = String(value).trim();
  if (!str) return true;
  const placeholders = ['Not provided', 'Undefined', 'Null', 'N/A', '*', 'Unknown'];
  return placeholders.some(p => str === p || str.toLowerCase() === p.toLowerCase());
}

function normalizeFileName(name) {
  return String(name || "ATS_Optimized_CV")
    .trim()
    .replace(/[^\p{L}\p{N}]+/gu, "_")
    .replace(/^_+|_+$/g, "") || "ATS_Optimized_CV";
}

// تحسين دالة التحقق من الرابط – متسامحة أكثر
function isValidUrl(string) {
  if (!string || typeof string !== "string") return false;
  let url = string.trim();
  if (!/^https?:\/\//i.test(url)) {
    url = "https://" + url;
  }
  try {
    new URL(url);
    return true;
  } catch (_) {
    return false;
  }
}

// دالة لاستخراج الروابط من أي كائن، بغض النظر عن المفتاح
function extractUrlsFromObject(obj, depth = 0) {
  const results = [];
  if (!obj || typeof obj !== "object") return results;
  const urlKeys = new Set(['github', 'linkedin', 'portfolio', 'website', 'url', 'link', 'repoUrl', 'demoUrl', 'credentialUrl']);

  for (const [key, val] of Object.entries(obj)) {
    if (typeof val === "string" && val.trim()) {
      if (urlKeys.has(key.toLowerCase()) && isValidUrl(val)) {
        const label = key.replace(/_/g, " ").replace(/\b\w/g, c => c.toUpperCase());
        results.push({ label, url: val });
      } else if (isValidUrl(val)) {
        const label = key.replace(/_/g, " ").replace(/\b\w/g, c => c.toUpperCase());
        results.push({ label, url: val });
      }
    } else if (typeof val === "object" && val !== null && depth < 5) {
      results.push(...extractUrlsFromObject(val, depth + 1));
    }
  }
  return results;
}

function linkText(url) {
  return url.replace(/^https?:\/\//i, "").replace(/^www\./i, "").replace(/\/$/g, "");
}

// دالة لضمان أن القيمة نصية (إذا كانت مصفوفة نأخذ العنصر الأول، وإلا نحول إلى نص)
function ensureString(value) {
  if (value == null) return "";
  if (Array.isArray(value)) {
    // نأخذ أول عنصر غير فارغ
    for (const item of value) {
      if (item != null && String(item).trim() !== "") {
        return String(item).trim();
      }
    }
    return "";
  }
  return String(value).trim();
}

// ----------------------------------------------------------------------------
// 2. NORMALIZATION LAYER (مُحسَّن)
// ----------------------------------------------------------------------------

const fieldMappings = {
  experience: {
    title: ['job_title', 'jobTitle', 'title', 'role'],
    subtitle: ['company', 'organization'],
    location: ['location'],
    date: ['start_date', 'startDate', 'end_date', 'endDate', 'dates', 'duration', 'period'],
    bullets: ['bullets', 'responsibilities', 'achievements', 'highlights'],
    description: ['description', 'summary'],
  },
  projects: {
    title: ['name', 'title'],
    subtitle: ['technologies', 'tech', 'techStack', 'stack'],
    date: ['date', 'year', 'dates'],
    link: ['link', 'url', 'repoUrl', 'demoUrl', 'github'],
    bullets: ['bullets'],
    description: ['description', 'summary'],
  },
  education: {
    title: ['degree', 'title'],
    subtitle: ['institution', 'university', 'school'],
    location: ['location'],
    date: ['start_date', 'startDate', 'end_date', 'endDate', 'dates', 'year'],
  },
  certifications: {
    title: ['name', 'title'],
    subtitle: ['provider', 'issuer', 'institution', 'organization'],
    date: ['date', 'year'],
    link: ['credentialUrl', 'url', 'link'],
  },
  languages: {
    title: ['language', 'name'],
    subtitle: ['proficiency', 'level'],
  },
};

function normalizeItem(item, mapping) {
  const result = {};
  for (const [canonical, aliases] of Object.entries(mapping)) {
    let value = null;
    for (const alias of aliases) {
      const candidate = item[alias];
      if (candidate != null && String(candidate).trim() !== "") {
        value = candidate;
        break;
      }
    }
    if (canonical === 'bullets') {
      // bullets يمكن أن تكون مصفوفة أو نص مفصول بفواصل
      if (typeof value === 'string') {
        result[canonical] = value.split(/\s*,\s*/).filter(Boolean);
      } else if (Array.isArray(value)) {
        result[canonical] = value.filter(v => v != null && String(v).trim() !== "");
      } else {
        result[canonical] = [];
      }
    } else if (canonical === 'subtitle' && Array.isArray(value)) {
      // إذا كانت التقنيات مصفوفة، نحولها إلى نص مفصول بفواصل
      result[canonical] = value.filter(v => v != null && String(v).trim() !== "").join(", ");
    } else {
      // جميع الحقول الأخرى يجب أن تكون نصية
      result[canonical] = ensureString(value);
    }
  }
  // حفظ الحقول الإضافية
  const extra = {};
  for (const [key, val] of Object.entries(item)) {
    if (!Object.values(mapping).flat().includes(key) && !['bullets','description','subtitle','date','link','title','location'].includes(key)) {
      if (val != null && String(val).trim() !== "") {
        extra[key] = val;
      }
    }
  }
  result._extra = extra;
  return result;
}

function normalizeCV(raw) {
  const result = {
    summary: "",
    sections: [],
    contacts: [],
    skills: null,
    personal: { name: "", title: "", location: "", phone: "", email: "" }
  };

  // --- بيانات شخصية ---
  const personal = raw.personal_info || raw.personalInfo || raw.contact || {};
  result.personal.name = ensureString(firstNonEmpty(personal.full_name, personal.fullName, personal.name, raw.full_name, raw.name));
  result.personal.title = ensureString(firstNonEmpty(personal.headline, raw.headline, raw.title, personal.title));
  result.personal.location = ensureString(firstNonEmpty(personal.location, raw.location));
  result.personal.phone = ensureString(firstNonEmpty(personal.phone, raw.phone));
  result.personal.email = ensureString(firstNonEmpty(personal.email, raw.email));

  // --- استخراج الروابط من الكائن بالكامل ---
  const allUrls = extractUrlsFromObject(raw);
  // أضف أيضاً أي روابط موجودة في الحقول المعروفة مثل github, linkedin على المستوى الجذري
  const rootUrlKeys = ['github', 'linkedin', 'portfolio', 'website'];
  for (const key of rootUrlKeys) {
    const val = raw[key];
    if (val && typeof val === "string" && isValidUrl(val)) {
      const label = key.replace(/_/g, " ").replace(/\b\w/g, c => c.toUpperCase());
      allUrls.push({ label, url: val });
    }
  }
  // إزالة التكرار
  const seen = new Set();
  for (const contact of allUrls) {
    if (!seen.has(contact.url)) {
      seen.add(contact.url);
      result.contacts.push(contact);
    }
  }

  // --- الملخص ---
  result.summary = ensureString(firstNonEmpty(raw.professional_summary, raw.professionalSummary, raw.summary, raw.profile, ""));

  // --- المهارات ---
  const skillsData = raw.skills || {};
  if (Array.isArray(skillsData)) {
    result.skills = { "Skills": skillsData.filter(s => !isPlaceholder(s)) };
  } else if (typeof skillsData === "object" && Object.keys(skillsData).length) {
    result.skills = {};
    for (const [cat, vals] of Object.entries(skillsData)) {
      let cleaned = [];
      if (Array.isArray(vals)) {
        cleaned = vals.filter(v => !isPlaceholder(v));
      } else if (typeof vals === "string") {
        cleaned = [vals].filter(v => !isPlaceholder(v));
      } else if (typeof vals === "object" && vals !== null) {
        const flat = Object.values(vals).filter(v => typeof v === "string" && !isPlaceholder(v));
        if (flat.length) cleaned = flat;
        else {
          for (const v of Object.values(vals)) {
            if (Array.isArray(v)) {
              const sub = v.filter(s => typeof s === "string" && !isPlaceholder(s));
              cleaned.push(...sub);
            }
          }
        }
      }
      if (cleaned.length) result.skills[cat] = cleaned;
    }
  }

  // --- بناء الأقسام ---
  // 1. الملخص
  if (result.summary && !isPlaceholder(result.summary)) {
    result.sections.push({
      type: 'summary',
      title: 'Professional Summary',
      items: [{ title: result.summary, subtitle: '', location: '', date: '', bullets: [], description: '', link: '', _extra: {} }]
    });
  }

  // 2. المهارات
  if (result.skills && Object.keys(result.skills).length) {
    result.sections.push({ type: 'skills', title: 'Technical Skills', items: [] });
  }

  // 3. الخبرات
  const exp = toArray(raw.experience || raw.workExperience || raw.professionalExperience);
  if (exp.length) {
    const items = exp.map(item => normalizeItem(item, fieldMappings.experience));
    result.sections.push({ type: 'experience', title: 'Experience', items });
  }

  // 4. المشاريع
  const proj = toArray(raw.projects);
  if (proj.length) {
    const items = proj.map(item => normalizeItem(item, fieldMappings.projects));
    result.sections.push({ type: 'projects', title: 'Projects', items });
  }

  // 5. التعليم
  const edu = toArray(raw.education || raw.academicBackground);
  if (edu.length) {
    const items = edu.map(item => normalizeItem(item, fieldMappings.education));
    result.sections.push({ type: 'education', title: 'Education', items });
  }

  // 6. الشهادات
  const certs = toArray(raw.certifications);
  if (certs.length) {
    const items = certs.map(item => normalizeItem(item, fieldMappings.certifications));
    result.sections.push({ type: 'certifications', title: 'Certifications', items });
  }

  // 7. اللغات
  const langs = toArray(raw.languages);
  if (langs.length) {
    const items = langs.map(item => normalizeItem(item, fieldMappings.languages));
    result.sections.push({ type: 'languages', title: 'Languages', items });
  }

  // 8. الأقسام الإضافية (مع استثناء الحقول الشخصية)
  const personalFields = new Set([
    'name', 'full_name', 'fullName', 'title', 'headline', 'target_role',
    'location', 'phone', 'email', 'github', 'linkedin', 'portfolio', 'website',
    'personal_info', 'personalInfo', 'contact', 'links', 'social', 'contact_links'
  ]);
  const consumedKeys = new Set([
    'professional_summary', 'professionalSummary', 'summary', 'profile',
    'skills',
    'experience', 'workExperience', 'professionalExperience',
    'projects',
    'education', 'academicBackground',
    'certifications',
    'languages',
    'optimized_cv', 'cv', 'optimizedCV', 'analysis'
  ]);
  for (const f of personalFields) consumedKeys.add(f);

  for (const [key, val] of Object.entries(raw)) {
    if (consumedKeys.has(key)) continue;
    if (Array.isArray(val) && val.length) {
      const genericMapping = {
        title: ['name', 'title', 'label'],
        subtitle: ['subtitle', 'provider', 'organization'],
        date: ['date', 'year', 'dates'],
        link: ['url', 'link'],
        bullets: ['bullets', 'highlights', 'achievements'],
        description: ['description', 'summary'],
      };
      const items = val.map(item => {
        if (typeof item === "string") {
          return { title: item, subtitle: '', location: '', date: '', bullets: [], description: '', link: '', _extra: {} };
        }
        if (typeof item === "object" && item !== null) {
          return normalizeItem(item, genericMapping);
        }
        return null;
      }).filter(Boolean);
      if (items.length) {
        const title = key.replace(/_/g, " ").replace(/\b\w/g, c => c.toUpperCase());
        result.sections.push({ type: 'generic', title, items });
      }
    } else if (typeof val === "string" && val.trim() && !isPlaceholder(val)) {
      if (!isValidUrl(val)) {
        const title = key.replace(/_/g, " ").replace(/\b\w/g, c => c.toUpperCase());
        result.sections.push({ type: 'generic', title, items: [{ title: val, subtitle: '', location: '', date: '', bullets: [], description: '', link: '', _extra: {} }] });
      }
    }
  }

  return result;
}

// ----------------------------------------------------------------------------
// 3. RENDER HELPERS (مع تحسين عرض الروابط)
// ----------------------------------------------------------------------------

function renderSkillGroup(label, items) {
  const values = toArray(items).filter(v => !isPlaceholder(v));
  if (!values.length) return "";
  const labelStr = label.replace(/_/g, " ").replace(/\b\w/g, c => c.toUpperCase());
  return `<div class="skill-cell"><strong>${esc(labelStr)}:</strong> ${values.map(esc).join(", ")}</div>`;
}

function renderBullets(items) {
  const values = toArray(items).filter(v => v && !isPlaceholder(v));
  if (!values.length) return "";
  const cleaned = values.map(bullet => {
    let b = String(bullet).trim();
    b = b.replace(/\b(in order to|a wide range of|various(?:ly)?|on a regular basis|as well as|with the goal of|for the purpose of)\b/gi, "");
    b = b.replace(/\s{2,}/g, " ").trim();
    b = b.charAt(0).toUpperCase() + b.slice(1);
    return b;
  }).filter(Boolean);
  if (!cleaned.length) return "";
  return `<ul>${cleaned.map(item => `<li>${esc(item)}</li>`).join("")}</ul>`;
}

function renderItemsSection(title, items, type) {
  if (!items || !items.length) return "";
  const html = items.map(item => {
    // جميع الحقول النصية مضمونة أن تكون سلاسل نصية بفضل ensureString في normalizeItem
    const titleStr = item.title ? `<span class="item-title">${esc(item.title)}</span>` : "";
    const subtitleStr = item.subtitle ? `<span class="item-subtitle">${esc(item.subtitle)}</span>` : "";
    const locationStr = item.location ? `<span class="item-location">(${esc(item.location)})</span>` : "";
    const bulletsHtml = renderBullets(item.bullets);
    const descHtml = item.description ? `<div class="desc">${esc(item.description)}</div>` : "";

    let header = "";
    let content = "";

    if (type === 'projects') {
      // item.link مضمون أنه نص (فارغ أو رابط)
      let linkStr = "";
      if (item.link && !isPlaceholder(item.link)) {
        let url = item.link.trim();
        if (!/^https?:\/\//i.test(url)) {
          url = "https://" + url;
        }
        const display = linkText(url);
        linkStr = `<span class="project-link"><a class="link" href="${esc(url)}" target="_blank" rel="noopener">${esc(display)}</a></span>`;
      }
      const techStr = item.subtitle ? `<span class="tech-stack">${esc(item.subtitle)}</span>` : "";
      header = `<div class="item-header">${titleStr}${techStr}${linkStr}</div>`;
      content = descHtml + (bulletsHtml ? (descHtml ? " " : "") + bulletsHtml : "");
    } else {
      const dateStr = (item.date && !isPlaceholder(item.date)) ? `<span class="item-date">${esc(item.date)}</span>` : "";
      let linkStr = "";
      if (item.link && !isPlaceholder(item.link)) {
        let url = item.link.trim();
        if (!/^https?:\/\//i.test(url)) {
          url = "https://" + url;
        }
        const display = linkText(url);
        linkStr = `<span class="item-date"><a class="link" href="${esc(url)}" target="_blank" rel="noopener">${esc(display)}</a></span>`;
      }
      const dateLink = dateStr + (dateStr && linkStr ? " | " : "") + linkStr;
      header = `<div class="item-header">
        <span class="item-title">${titleStr} ${subtitleStr} ${locationStr}</span>
        ${dateLink ? `<span class="item-date">${dateLink}</span>` : ""}
      </div>`;
      content = bulletsHtml || descHtml;
    }

    return `<div class="item ${type}-item">${header}${content}</div>`;
  }).join("");
  return `<section><h2>${esc(title)}</h2><div class="section-body">${html}</div></section>`;
}

// ----------------------------------------------------------------------------
// 4. MAIN RENDER – with error handling
// ----------------------------------------------------------------------------

try {
  if (!input || Object.keys(input).length === 0) {
    return {
      json: {
        ok: false,
        success: false,
        status: "empty_input",
        error: "No input data provided.",
        chat_id: String(data.chat_id || data.chatId || ""),
      }
    };
  }

  const normalized = normalizeCV(input);

  const hasContent = normalized.personal.name !== "Candidate" || 
                     normalized.summary || 
                     normalized.sections.some(s => s.items && s.items.length > 0);
  if (!hasContent) {
    return {
      json: {
        ok: false,
        success: false,
        status: "no_content",
        error: "No usable CV fields found after normalization.",
        chat_id: String(data.chat_id || data.chatId || ""),
      }
    };
  }

  let candidateName = normalized.personal.name || "Candidate";
  if (isPlaceholder(candidateName)) candidateName = "Candidate";
  const displayName = candidateName;

  const title = normalized.personal.title || "";
  const location = normalized.personal.location || "";
  const phone = normalized.personal.phone || "";
  const email = normalized.personal.email || "";

  // سطر الاتصال الأول
  let contactLine1Parts = [];
