function esc(value) {
  return String(value ?? "")
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;")
    .replace(/'/g, "&#039;");
}

function arr(value) {
  if (!value) return [];

  if (Array.isArray(value)) {
    return value.filter(item => {
      if (!item) return false;

      if (typeof item === "object") {
        return Object.values(item).some(v => {
          if (Array.isArray(v)) return v.length > 0;
          return v !== null && v !== undefined && String(v).trim() !== "";
        });
      }

      return String(item).trim() !== "";
    });
  }

  if (typeof value === "string") {
    return value
      .split(/\n|•|,/)
      .map(x => x.trim())
      .filter(Boolean);
  }

  return [];
}

function firstNonEmpty(...values) {
  for (const value of values) {
    if (value === null || value === undefined) continue;

    if (Array.isArray(value) && value.length) return value;

    if (
      typeof value === "object" &&
      !Array.isArray(value) &&
      Object.keys(value).length
    ) {
      return value;
    }

    if (typeof value !== "object" && String(value).trim() !== "") {
      return value;
    }
  }

  return "";
}

function normalizeFileName(name) {
  return String(name || "ATS_Optimized_CV")
    .trim()
    .replace(/[^\p{L}\p{N}]+/gu, "_")
    .replace(/^_+|_+$/g, "") || "ATS_Optimized_CV";
}

function truncateWords(text, maxWords = 25) {
  const words = String(text || "").trim().split(/\s+/).filter(Boolean);
  if (!words.length) return "";
  if (words.length <= maxWords) return words.join(" ");
  return words.slice(0, maxWords).join(" ").replace(/[.,;:]+$/, "") + "...";
}

function dedupeCaseInsensitive(list) {
  const seen = new Set();
  const out = [];
  for (const item of list) {
    const key = String(item).trim().toLowerCase();
    if (!key || seen.has(key)) continue;
    seen.add(key);
    out.push(item);
  }
  return out;
}

function dedupeAgainst(list, seenSet) {
  const out = [];
  for (const item of list) {
    const key = String(item).trim().toLowerCase();
    if (!key || seenSet.has(key)) continue;
    seenSet.add(key);
    out.push(item);
  }
  return out;
}

function isSkillRestatement(bulletText, skillSet) {
  if (!skillSet.size) return false;
  const words = String(bulletText)
    .toLowerCase()
    .split(/[^a-z0-9+.#]+/)
    .filter(Boolean);
  if (!words.length || words.length > 10) return false;
  const matches = words.filter(w => skillSet.has(w));
  return matches.length / words.length >= 0.5;
}

function buildExperienceParagraph(items, maxSentences = 2) {
  const cleaned = items
    .map(b => String(b).trim().replace(/[.\s]+$/, ""))
    .filter(Boolean);

  const capped = cleaned.slice(0, maxSentences);
  if (!capped.length) return "";

  return capped.map(s => `${s}.`).join(" ");
}

function renderSkillGroup(label, items) {
  const values = arr(items);
  if (!values.length) return "";

  return `
    <p class="skill-line">
      <strong>${esc(label)}:</strong> ${values.map(esc).join(", ")}.
    </p>
  `;
}

function renderBullets(items, max = 3) {
  const values = arr(items).slice(0, max);
  if (!values.length) return "";

  return `
    <ul>
      ${values.map(item => `<li>${esc(item)}</li>`).join("")}
    </ul>
  `;
}

function renderSection(title, body) {
  if (!body || !String(body).trim()) return "";

  return `
    <section>
      <h2>${esc(title)}</h2>
      ${body}
    </section>
  `;
}

function linkText(value) {
  return String(value || "")
    .replace(/^https?:\/\//i, "")
    .replace(/\/$/g, "");
}

function isRealLink(value) {
  const link = String(value || "").trim();

  return (
    /^https?:\/\//i.test(link) ||
    /github\.com|linkedin\.com|web\.app|netlify\.app|vercel\.app/i.test(link)
  );
}

function makeUrl(url) {
  if (!url) return "";

  const clean = String(url).trim();

  return clean.startsWith("http")
    ? clean
    : `https://${clean}`;
}

const personal =
