const density =
  rawExperience.reduce(
    (sum, e) => sum + arr(e.bullets || e.responsibilities || e.achievements).length,
    0
  ) +
  rawProjects.length * 2 +
  rawEducation.length;

const isDense = density > 14;

const EXP_SENTENCE_MAX = 2;
const PROJECT_MAX = isDense ? 2 : 3;
