  .page {
    width: 210mm;
    min-height: 297mm;
    padding: 14mm 18mm;
    margin: 0 auto;
    background: #ffffff;
  }

  header {
    text-align: center;
    padding-bottom: 12px;
    margin-bottom: 14px;
  }

  h1 {
    margin: 0;
    font-size: 28px;
    line-height: 1.1;
    font-weight: 600;
    text-transform: uppercase;
    letter-spacing: 0.3px;
  }

  .title {
    margin-top: 8px;
    font-size: 12px;
    font-weight: 400;
  }

  .contact {
    margin-top: 8px;
    font-size: 10.2px;
    color: #111111;
    word-break: break-word;
    line-height: 1.8;
  }

  .contact span:not(:last-child)::after {
    content: " | ";
    color: #111111;
  }

  .link {
    color: #0066cc;
  }

  a.link {
    color: #0066cc;
    text-decoration: none;
  }

  a.link:hover {
    text-decoration: underline;
  }

  section {
    margin-top: 13px;
  }

  h2 {
    margin: 0 0 9px 0;
    padding-bottom: 4px;
    border-bottom: 1px solid #d0d0d0;
    font-size: 14px;
    line-height: 1.2;
    font-weight: 700;
    text-transform: uppercase;
    letter-spacing: 0.2px;
  }

  p {
    margin: 0 0 6px 0;
  }

  .skill-line {
    margin: 0 0 5px 0;
  }

  .item {
    margin-bottom: 7px;
    break-inside: avoid;
  }

  .project-item {
    margin-bottom: 8px;
  }

  .item-header {
    display: flex;
    justify-content: space-between;
    gap: 14px;
    font-weight: 700;
  }

  .item-title {
    flex: 1;
  }

  .item-date {
    white-space: nowrap;
    text-align: right;
    color: #111111;
    font-size: 10px;
    font-weight: 700;
  }

  .sub {
    margin-top: 2px;
    color: #333333;
    font-size: 10.4px;
  }

  ul {
    margin: 3px 0 0 17px;
    padding: 0;
  }

  li {
    margin: 0 0 2px 0;
    padding: 0;
  }

  .desc {
    margin-top: 2px;
  }

  .footer-grid {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 18px;
  }
</style>
</head>

<body>
  <main class="page">

    <header>
      <h1>${esc(candidateName)}</h1>

      ${title ? `<div class="title">${esc(title)}</div>` : ""}

      <div class="contact">

        <div>
          ${location ? `<span>${esc(location)}</span>` : ""}
          ${phone ? `<span>${esc(phone)}</span>` : ""}
          ${email ? `<span>${esc(email)}</span>` : ""}
        </div>

        ${
          github || linkedin || portfolio
            ? `<div>
                ${github ? `
                  <span>
                    GitHub: <a href="${makeUrl(github)}" class="link" target="_blank">${esc(linkText(github))}</a>
                  </span>
                ` : ""}

                ${linkedin ? `
                  <span>
                    LinkedIn: <a href="${makeUrl(linkedin)}" class="link" target="_blank">${esc(linkText(linkedin))}</a>
                  </span>
                ` : ""}

                ${portfolio ? `
                  <span>
                    Portfolio: <a href="${makeUrl(portfolio)}" class="link" target="_blank">${esc(linkText(portfolio))}</a>
                  </span>
                ` : ""}
              </div>`
            : ""
        }

      </div>
    </header>

    ${
      summary
        ? `<section>
            <h2>Professional Summary</h2>
            <p>${esc(summary)}</p>
          </section>`
        : ""
    }

    ${renderSection("Experience", experienceHtml)}

    ${
      skillsHtml.trim()
        ? `<section>
            <h2>Skills</h2>
            ${skillsHtml}
          </section>`
        : ""
    }

    ${renderSection("Projects", projectsHtml)}
    ${renderSection("Education", educationHtml)}

    ${
      certificationsHtml || languagesHtml
        ? `<div class="footer-grid">
            ${renderSection("Certifications", certificationsHtml)}
            ${renderSection("Languages", languagesHtml)}
          </div>`
        : ""
    }

  </main>
</body>
</html>`;

const safeName = normalizeFileName(candidateName);
const pdfFileName = `${safeName}_ATS_Optimized_CV.pdf`;

const htmlBuffer = Buffer.from(html, "utf8");

const binaryData = await this.helpers.prepareBinaryData(
  htmlBuffer,
  "index.html",
  "text/html"
);

return {
  json: {
    ...data,

    ok: true,
    success: true,
    status: "ats_cv_html_built",

    chat_id: String(data.chat_id || data.chatId || ""),
    chatId: String(data.chatId || data.chat_id || ""),

    user_id: data.user_id,
    session_id: data.session_id,
    user_file_id: data.user_file_id,

    fileName: pdfFileName,
    file_name: pdfFileName,
    pdf_file_name: pdfFileName,

    html,
    html_length: html.length,
    html_ready: true
  },
  binary: {
    data: binaryData
  }
};
